//line postgres.y:15753

// rejectWithinGroupConflicts mirrors PostgreSQL gram.y: FuncCall has one AggOrder field shared by
// foo(... ORDER BY ...) and foo(...) WITHIN GROUP (ORDER BY ...), so conflicting decorations must
// fail before WITHIN GROUP replaces the plain aggregate ORDER BY list.
func rejectWithinGroupConflicts(yylex LexerInterface, funcCall *ast.FuncCall) {
	if funcCall.AggOrder != nil {
		withinGroupConflictError(yylex, "cannot use multiple ORDER BY clauses with WITHIN GROUP")
	}
	if funcCall.AggDistinct {
		withinGroupConflictError(yylex, "cannot use DISTINCT with WITHIN GROUP")
	}
	if funcCall.FuncVariadic {
		withinGroupConflictError(yylex, "cannot use VARIADIC with WITHIN GROUP")
	}
}

func grammarErrorWithFields(yylex LexerInterface, message, hint, sqlState string) {
	if lexer, ok := yylex.(interface {
		ErrorWithHintState(string, string, string)
	}); ok {
		lexer.ErrorWithHintState(message, hint, sqlState)
		return
	}
	yylex.Error(message)
}

func withinGroupConflictError(yylex LexerInterface, message string) {
	lexer, ok := yylex.(*Lexer)
	if !ok {
		yylex.Error(message)
		return
	}

	end := len(lexer.context.sourceText)
	if token := lexer.context.lastToken; token != nil && token.Position >= 0 && token.Position < end {
		end = token.Position
	}
	location := strings.LastIndex(strings.ToLower(lexer.context.sourceText[:end]), "within group")
	if location < 0 {
		yylex.Error(message)
		return
	}
	lexer.context.AddError(message, location)
}

// Lex implements the lexer interface for goyacc
func (l *Lexer) Lex(lval *yySymType) int {
	token := l.NextToken()
	// Remember the token handed to the parser so Error can report the token the
	// parse failed at (PostgreSQL's "at or near"). A nil token signals EOF.
	l.context.SetLastToken(token)
	if token == nil {
		return EOF // EOF = 0, exactly what yacc expects
	}

	// Set location and always populate both semantic value fields
	lval.location = token.Position
	lval.str = token.Value.Str
	lval.ival = token.Value.Ival

	// Simply return the token type - no complex switch needed!
	// All parser constants, keywords, operators, etc. work directly
	return token.Type
}

// Error implements the error interface for goyacc. It shapes the message and
// position to match PostgreSQL's scanner_yyerror ("syntax error at or near
// \"<token>\"" / "at end of input", with the position pointing at the offending
// token).
func (l *Lexer) Error(s string) {
	l.context.AddSyntaxError(s)
}

